window.NPC_CHUNK_217 = [{"name":"Brimstone","cr":5,"xp":1600,"race":"human","gender":"Female","age_category":"middle age","classes":[{"class":"barbarian","level":4,"archetype":"mad dog"},{"class":"cavalier","level":2,"archetype":"huntmaster"}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+8 armor, +1 Dex, -2 rage","hp":64,"hd":"4d12+2d10+22","hd_value":6,"fort":10,"ref":2,"will":3,"save_mods":"+3 vs. magic, Ref: +1 vs. traps","speed":[{"type":"land","speed":40}],"melee":"+1 greataxe +12 (1d12+7/x3)","ranged":"javelin +7 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bestial challenge","details":"+2, +1, 1/day"},{"type":"pack tactics"},{"type":"rage","details":"5 rounds/day"},{"type":"rage powers","details":"superstition +3"}],"strength":18,"dexterity":12,"constitution":17,"intelligence":13,"wisdom":11,"charisma":12,"baseatk":6,"cmb":10,"cmd":19,"feats":[{"feat":"Dazzling Display"},{"feat":"Dramatic Display"},{"feat":"Heavy Armor Proficiency"},{"feat":"Outflank"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greataxe)"}],"skills":[{"skill":"Acrobatics","value":8,"special":"+4 when jumping"},{"skill":"Appraise","value":6},{"skill":"Handle Animal","value":10},{"skill":"Intimidate","value":10},{"skill":"Knowledge (local)","value":2},{"skill":"Knowledge (nobility)","value":2},{"skill":"Perception","value":9},{"skill":"Perform (dance)","value":10},{"skill":"Profession (gladiatorial trainer)","value":5}],"languages":["Common","Hallit","Skald"],"sq":["fast movement","hunting pack (Brimstone [thylacine])","order of the cockatrice (braggart)","tactician (1/day, 4 rounds, standard action)"],"special_abilities":[{"type":"Bestial Challenge","kind":"Ex","details":"Whenever Helkit issues a challenge, both she and her hunting pack gain the bonuses and penalties associated with her challenge. This ability modifies a cavalier's challenge ability."},{"type":"Hunting Pack","kind":"Ex","details":"Helkit has gained the service of an animal companion, Brimstone. Her effective druid level is equal to her cavalier level."},{"type":"Pack Tactics","kind":"Ex","details":"Helkit and her war beast gain a +4 bonus on attack rolls while flanking the same opponent (instead of the normal +2 bonus)."},{"type":"Rage","kind":"Ex","details":"Helkit gains the rage barbarian class ability, except that her effective barbarian level for the ability is equal to her barbarian level - 3."},{"type":"Tactician","kind":"Ex","details":"A huntmaster's tactician ability affects only her hunting pack, not other allies. This modifies the tactician ability."},{"type":"War Beast","kind":"Ex","details":"Helkit has gained the service of an animal companion, Brimstone. Her effective druid level is equal to her barbarian level."}],"gear":"+1 piecemeal armor, +1 greataxe, javelins (3), 227 gp, potion of cure serious wounds, potion of enlarge person","during_combat":"Helkit drinks her potion of enlarge person once combat begins. If her Slayers are still faring well, she then moves closer and uses her Dazzling Display feat to demoralize as many PCs as she can. Her tactics are otherwise simple but brutal: she begins to rage, charges into melee, and makes judicious use of Power Attack and Dramatic Display while commanding Brimstone to flank with her.","morale":"Helkit yields if reduced to 15 hit points or fewer or if all but one of her allies (including Brimstone) fall. If the PCs \"accidentally\" ignore her surrender, she grits her teeth and fights to her death, cursing them for their dishonor.","base_statistics":"When not raging, Helkit's statistics are AC 19, touch 11, flat-footed 18; hp 56; Fort +8, Will +1; Melee +1 greataxe +10/+5 (1d12+4/x3); Ranged javelin +7 (1d6+2); Str 14, Con 13; CMB +8.","source":"PFS S5-06, Pathfinder RPG Advanced Player's Guide 32, Pathfinder Player Companion: Animal Archive 6, 7"},{"name":"Brimst One","xp":0,"race":"thylacine","gender":"Male","age_category":"Adult","classes":[{"class":"animal companion","level":6}],"alignment":"N","size":"Medium","type":"animal","init":3,"senses":["low-light vision"],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":57,"hd":"6d8+30","hd_value":6,"fort":10,"ref":8,"will":3,"save_mods":"Will: +4 vs. enchantments","speed":[{"type":"land","speed":30}],"melee":"bite +9 (1d6+6/19-20)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":16,"constitution":20,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":4,"cmb":8,"cmd":21,"cmd_special":"25 vs. trip","feats":[{"feat":"Intimidating Prowess"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Intimidate","value":6},{"skill":"Perception","value":9}],"sq":["devotion","evasion","link","powerful jaws","tricks (attack [all creatures], come, defend, down, fetch, flankAA, heel, perform)"],"during_combat":"Brimstone stays with Helkit, snarling and howling when his master uses Dazzling Display (using aid another to bolster Helkit's Intimidate check). He typically attacks the same target as Helkit.","morale":"Brimstone fights to the death or until called off by Helkit.","source":"PFS S5-06, Pathfinder RPG Bestiary 3 191, 312"},{"name":"Helkit Silverbane Subtier 6-7","cr":8,"xp":4800,"race":"human","gender":"Female","age_category":"middle age","classes":[{"class":"barbarian","level":5,"archetype":"mad dog"},{"class":"cavalier","level":4,"archetype":"huntmaster"}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+8 armor, +1 Dex, -2 rage","hp":101,"hd":"5d12+4d10+41","hd_value":9,"fort":12,"ref":3,"will":4,"save_mods":"+3 vs. magic, Ref: +1 vs. traps","speed":[{"type":"land","speed":40}],"melee":"+1 greataxe +15 (1d12+7/x3)","ranged":"javelin +10 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bestial challenge","details":"+4, +2, 2/day"},{"type":"pack tactics"},{"type":"rage","details":"8 rounds/day"},{"type":"rage powers","details":"superstition +3"},{"type":"takedown"}],"strength":18,"dexterity":12,"constitution":18,"intelligence":13,"wisdom":11,"charisma":12,"baseatk":9,"cmb":13,"cmd":22,"feats":[{"feat":"Dazzling Display"},{"feat":"Dramatic Display"},{"feat":"Heavy Armor Proficiency"},{"feat":"Hero's Display"},{"feat":"Masterful Display"},{"feat":"Outflank"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greataxe)"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+4 when jumping"},{"skill":"Appraise","value":6},{"skill":"Handle Animal","value":13},{"skill":"Intimidate","value":13},{"skill":"Knowledge (local)","value":3},{"skill":"Knowledge (nobility)","value":3},{"skill":"Perception","value":12},{"skill":"Perform (dance)","value":13},{"skill":"Profession (gladiatorial trainer)","value":6}],"languages":["Common","Hallit","Skald"],"sq":["animal trainer +2","fast movement","hunting pack (Brimstone [thylacine])","order of the cockatrice (braggart)","tactician (1/day, 5 rounds, standard action)","trap sense +1"],"special_abilities":[{"type":"Ferocious Fetch","kind":"Ex","details":"Helkit grants Brimstone Improved Drag as a bonus feat. As a swift action, Helkit can command Brimstone to move toward an opponent within 30 ft. and attempt a drag combat maneuver to pull the target back toward her. Brimstone can move before and after performing the maneuver, but this movement counts toward its total movement during its turn."},{"type":"Takedown","kind":"Ex","details":"Helkit grants Brimstone the takedown special ability, detailed further in its stat block."}],"gear":"+1 spell storing piecemeal armor (contains CL 5th vampiric touch), +1 greataxe, javelins (3), 77 gp, potion of cure serious wounds, potion of enlarge person, potion of haste","during_combat":"Helkit drinks either her potion of enlarge person or potion of haste once combat begins, depending on which would be more advantageous. If her Slayers are still faring well, she moves closer and uses her Dazzling Display feat to demoralize as many PCs as she can. Her tactics are otherwise simple but brutal: she begins to rage, charges into melee, and makes judicious use of Power Attack and her performance combat feats while commanding Brimstone to flank with her.","morale":"Helkit yields if reduced to 25 hit points or fewer or if all but one of her allies (including Brimstone) fall. If the PCs \"accidentally\" ignore her surrender, she grits her teeth and fights to her death, cursing them for their dishonor.","base_statistics":"When not raging, Helkit's statistics are AC 19, touch 11, flatfooted 18; hp 92; Fort +10, Will +2; Melee +1 greataxe +15/+10 (1d12+7/x3); Ranged javelin +10 (1d6+2); Str 14, Con 14; CMB +11.","source":"PFS S5-06, Pathfinder RPG Advanced Player's Guide 32, Pathfinder Player Companion: Animal Archive 6, 7"},{"name":"Brimstone Subtier 6-7","xp":0,"race":"Thylacine","gender":"Male","age_category":"Adult","classes":[{"class":"animal companion","level":9}],"alignment":"N","size":"Medium","type":"animal","init":3,"senses":["low-light vision"],"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+3 Dex, +8 natural","hp":76,"hd":"8d8+40","hd_value":8,"fort":11,"ref":9,"will":3,"speed":[{"type":"land","speed":30}],"melee":"bite +12 (1d8+7 plus takedown/19-20)","space":"5 ft.","reach":"5 ft.","strength":20,"dexterity":17,"constitution":20,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":6,"cmb":11,"cmd":24,"cmd_special":"28 vs. trip","feats":[{"feat":"Improved Drag"},{"feat":"Improved Natural Attack (bite)","type":"bonus"},{"feat":"Intimidating Prowess"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Intimidate","value":7},{"skill":"Perception","value":10}],"sq":["devotion","evasion","link","powerful jaws","tricks (attack [all creatures], come, defend, down, fetch, flankAA, heel, perform, stay)"],"special_abilities":[{"type":"Takedown","kind":"Ex","details":"Brimstone can make a free trip or dirty trick (entangled) combat maneuver after a successful melee attack. These combat maneuvers don't provoke attacks of opportunity."}],"during_combat":"Brimstone stays with Helkit, snarling and howling when his master uses Dazzling Display (using aid another to bolster Helkit's Intimidate check). He typically attacks the same target as Helkit.","morale":"Brimstone fights to the death or until called off by Helkit.","source":"PFS S5-06, Pathfinder RPG Bestiary 3 191, 312"},{"name":"Pure Legion Enforcer","cr":4,"xp":1200,"race":"human","age_category":"Adult","classes":[{"class":"ranger","level":5,"archetype":"skirmisher"}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+5 armor, +2 Dex, +1 dodge","hp":42,"hd":"5d10+10","hd_value":5,"fort":5,"ref":6,"will":3,"save_mods":"+1 vs. divine spells","speed":[{"type":"land","speed":30}],"melee":"mwk scimitar +10 (1d6+3/18-20)","ranged":"mwk composite longbow +8 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"archery"},{"type":"favored enemy","details":"humans +4, native outsiders +2"}],"strength":17,"dexterity":14,"constitution":12,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":5,"cmb":8,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Godless Healing"},{"feat":"Precise Shot"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Heal","value":6},{"skill":"Intimidate","value":6},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":9},{"skill":"Survival","value":10}],"languages":["Common","Osiriani"],"sq":["favored terrain (desert +2)","hunter's bond (companions)","hunter's tricks 4/day (hateful attack)","track +2","wild empathy +4"],"gear":"+1 leather lamellar, mwk composite longbow with 20 arrows, mwk scimitar, elixir of truth, robe of the pure legion +1, lock (good), manacles","during_combat":"The legionnaires employ their bows and scimitars to strike down perceived criminals, preferring divine spellcasters and favored enemies as targets and using their hateful strike ability. After the first few rounds of combat, they begin dealing nonlethal damage so long as they appear to have a clear advantage; against powerful enemies, the legionnaires deal lethal damage. They try to take at least one prisoner for questioning later.","morale":"Once all but one of the legionnaires have fallen, the last soldier attempts to withdraw and seek reinforcements.","source":"PFS S5-07, Pathfinder RPG Advanced Player's Guide 128"},{"name":"Pure Legion Enforcer Subtier 8-9","cr":7,"xp":3200,"race":"human","age_category":"Adult","classes":[{"class":"ranger","level":8,"archetype":"skirmisher"}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+5 armor, +2 Dex, +1 dodge","hp":72,"hd":"8d10+24","hd_value":8,"fort":7,"ref":8,"will":4,"save_mods":"+2 vs. divine spells","speed":[{"type":"land","speed":30}],"melee":"+1 scimitar +14 (1d6+7/18-20)","ranged":"mwk composite longbow +11 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"archery"},{"type":"favored enemy","details":"humans +4, native outsiders +2"}],"strength":18,"dexterity":14,"constitution":12,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":8,"cmb":12,"cmd":25,"feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Godless Healing"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Heal","value":6},{"skill":"Intimidate","value":9},{"skill":"Knowledge (local)","value":8},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":12},{"skill":"Survival","value":13}],"languages":["Common","Osiriani"],"sq":["favored terrain (desert +4, urban +2)","hunter's bond (companions)","hunter's tricks 6/day (hateful attack, uncanny senses)","swift tracker","track +4","wild empathy +7","woodland stride"],"gear":"+1 leather lamellar, +1 scimitar, mwk composite longbow with 20 arrows, elixir of truth, robe of the pure legion +2, lock (good), manacles","source":"PFS S5-07"},{"name":"Sophini","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"Blackfire Adept","level":3},{"class":"conjurer","level":5,"archetype":"teleportation"}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":59,"hd":"8d6+29","hd_value":8,"fort":6,"ref":5,"will":10,"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +3 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"shift","details":"10 feet"}]}],"spellsprepared_caster":"conjurer","spellsprepared_caster_level":7,"spellsprepared_concentration":11,"spellsprepared":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"crushing despair"},{"spell":"dimension door"},{"spell":"summon monster IV"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"heroism"},{"spell":"invisibility sphere"},{"spell":"spiked pit"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"create pit"},{"spell":"glitterdust"},{"spell":"scorching ray"},{"spell":"see invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from evil"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"light"}]}],"prohibited_schools":"necromancy, transmutation","strength":8,"dexterity":12,"constitution":14,"intelligence":18,"wisdom":14,"charisma":10,"baseatk":3,"cmb":2,"cmd":13,"feats":[{"feat":"Augment Summoning"},{"feat":"Combat Casting"},{"feat":"Improved Initiative"},{"feat":"Sacred Summons (evil)"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus  (conjuration)"},{"feat":"Spell Mastery"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":11},{"skill":"Diplomacy","value":8},{"skill":"Fly","value":7},{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Linguistics","value":10},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":15}],"languages":["Common","Abyssal","Azlanti","Celestial","Infernal","Osiriani","Thassilonian"],"sq":["arcane bond (dagger)","summoner's charm (2 rounds)"],"special_abilities":[{"type":"Blackfire Pact","kind":"Su","details":"Sophini gains a +1 profane bonus on saving throws, caster level checks, Charisma checks, and Charisma-based skill checks against daemons."},{"type":"Blackfire Taint","kind":"Su","details":"As a standard action, Sophini can create a destructive resonance between herself and a target within 30 feet. She gains a +1 profane bonus on attack rolls and caster level checks against the target, and the target takes a -1 penalty on saving throws against Sophini's attacks (-2 if the attack is a conjuration effect). The taint lasts for 3 rounds, though a successful DC 13 Will save reduces this to 1 round. The effect ends immediately if the target moves more than 30 ft. away from Sophini."},{"type":"Expanded Summoning List","kind":"Su","details":"Sophini is able to summon a vargouille with summon monster III, and she can summon a yeth hound with summon monster IV. These are in addition to her normal options when casting summon monster spells."}],"gear":"mwk dagger, cloak of resistance +2, spell component pouch (2), spellbook (contains all memorized spells plus acid arrow, alarm, color spray, summon monster I, summon monster II, and vampiric touch), 268 gp, potion of cure moderate wounds, scroll of arcane eye, scroll of blur, scroll of shield, scroll of wind wall, wand of mirror image (13 charges)","before_combat":"Sophini casts mage armor, mirror image, heroism, see invisibility, invisibility sphere, and shield when she senses trouble, such as if she sees a blackfire candle glowing or hears an alarm. She then continues her interrogation of Jahani while both she and the Riftwarden are invisible.","during_combat":"Sophini summons allies while invisible and then employs a combination of area control spells and offensive spells to divide and strike down her enemies. She makes regular use of her shift arcane school ability to stay out of reach.","morale":"If Sophini reduced below 30 hit points but believes she still has many allies in the compound, she casts dimension door to rally the ceustodaemons and guards to attack while she spends several rounds recuperating. She then renews the attack. If Sophini has reason to believe that her allies were defeated, she fights until reduced to 15 or fewer hit points before using dimension door to teleport away.","source":"PFS S5-07, Pathfinder RPG Advanced Player's Guide 147, Pathfinder Campaign Setting: Paths of Prestige 12"},{"name":"Sophini Subtier 8-9","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"Blackfire Adept","level":6},{"class":"conjurer","level":5,"archetype":"teleportation"}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":79,"hd":"11d6+38","hd_value":11,"fort":7,"ref":6,"will":11,"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +5 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"shift","details":"10 feet"}]}],"spellsprepared_caster":"conjurer","spellsprepared_caster_level":9,"spellsprepared_concentration":14,"spellsprepared":[{"spell_level":5,"spell_slots":3,"spells":[{"spell":"hold person"},{"spell":"summon monster V"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"},{"spell":"crushing despair"},{"spell":"dimension door"},{"spell":"summon monster IV"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"heroism"},{"spell":"invisibility sphere"},{"spell":"spiked pit"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"create pit"},{"spell":"glitterdust"},{"spell":"scorching ray"},{"spell":"see invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"protection from evil"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"light"}]}],"prohibited_schools":"necromancy, transmutation","strength":8,"dexterity":12,"constitution":14,"intelligence":20,"wisdom":14,"charisma":10,"baseatk":5,"cmb":4,"cmd":15,"feats":[{"feat":"Augment Summoning"},{"feat":"Combat Casting"},{"feat":"Greater Spell Focus (conjuration)"},{"feat":"Improved Initiative"},{"feat":"Sacred Summons","type":"bonus"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (conjuration)"},{"feat":"Spell Mastery"},{"feat":"Spell Penetration"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":11},{"skill":"Knowledge (arcana)","value":19},{"skill":"Knowledge (local)","value":19},{"skill":"Knowledge (planes)","value":19},{"skill":"Knowledge (religion)","value":17},{"skill":"Linguistics","value":11},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":16},{"skill":"Spellcraft","value":19}],"languages":["Common","Abyssal","Aklo","Azlanti","Celestial","Draconic","Infernal","Osiriani","Thassilonian"],"sq":["arcane bond (dagger)","summoner's charm (2 rounds)"],"special_abilities":[{"type":"Blackfire Eruption","kind":"Sp","details":"Sophini can sacrifice a prepared spell of 4th level or lower to call forth a searing ebon vortex that acts like unholy blight, it ignores the hardness of objects. A creature slain or an object destroyed by a blackfire eruption is reduced to ash as by the disintegrate spell. This is a conjuration effect."},{"type":"Blackfire Pact","kind":"Su","details":"Sophini gains a +1 profane bonus on saving throws, caster level checks, Charisma checks, and Charisma-based skill checks against divs. She gains a +2 profane bonus on such rolls against daemons."},{"type":"Blackfire Taint","kind":"Su","details":"As a standard action, Sophini can create a destructive resonance between herself and a target within 30 feet. She gains a +2 profane bonus on attack rolls and caster level checks against the target, and the target takes a -2 penalty on saving throws against Sophini's attacks (-3 if the attack is a conjuration effect). The taint lasts for 6 rounds, though a successful DC 16 Will save reduces this to 1 round. The effect ends immediately if the target moves more than 30 ft. away from Sophini."},{"type":"Breaching","kind":"Su","details":"When Sophini attempts to call or summon a daemon or div into an area where summoning is blocked by a magical effect (such as magic circle against evil), or when a daemon or div within 30 ft. she had summoned would have its attacks against a creature blocked by such an effect, as a swift action she can sacrifice a prepared spell of the same level as the warding effect. If her caster level is higher than the caster level of the warding effect, it is immediately negated. If it is the same level or lower, a caster level check (DC 11 + the caster level of the warding) is required to negate the effect."},{"type":"Expanded Summoning List","kind":"Su","details":"Sophini is able to summon a vargouille with summon monster III, and she can summon a yeth hound with summon monster IV. These are in addition to her normal options when casting summon monster spells."}],"gear":"mwk dagger, cloak of resistance +2, headband of vast intelligence +2, spell component pouch (2), spellbook (contains all memorized spells plus acid arrow, alarm, burning hands, color spray, fly, summon monster I, summon monster II, teleport, and vampiric touch), 243 gp, lesser silent metamagic rod, potion of cure moderate wounds, scroll of arcane eye, scroll of blur, scroll of shield, scroll of wind wall, wand of clairaudience/ clairvoyance (7 charges), wand of mirror image (13 charges)","before_combat":"Sophini casts mage armor, mirror image, heroism, see invisibility, invisibility sphere, and shield when she senses trouble, such as if she sees a blackfire candle glowing or hears an alarm. She then continues her interrogation of Jahani while both she and the Riftwarden are invisible.","during_combat":"Sophini summons allies while invisible and then employs a combination of area control spells and offensive spells to divide and strike down her enemies. She makes regular use of her shift arcane school ability to stay out of reach.","morale":"If Sophini is reduced below 40 hit points but believes that she still has many allies in the compound, she cast dimension door to rally the ceustodaemons and guards to attack while she spends several rounds recuperating. She then renews the attack. If Sophini has reason to believe that her allies were defeated, she fights until she's reduced to 20 or fewer hit points before using dimension door to teleport away.","source":"PFS S5-07, Pathfinder RPG Advanced Player's Guide 147, Pathfinder Campaign Setting: Paths of Prestige 12"},{"name":"Kortos Mosquito Swarm","cr":2,"xp":600,"race":"Kortos Mosquito Swarm","age_category":"Adult","alignment":"N","size":"Diminutive","type":"vermin","sub_types":["swarm"],"init":1,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 size","hp":14,"hd":"4d8-4","hd_value":4,"fort":3,"ref":2,"will":2,"defensive_abilities":["swarm traits"],"immunities":["mind-affecting effects","weapon damage"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":5}],"melee":"swarm (1d6 plus disease and bleed)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"bleed","details":"1d3"},{"type":"disease","details":"malaria, DC 11"},{"type":"distraction","details":"DC 11"}],"strength":1,"dexterity":13,"constitution":9,"wisdom":12,"charisma":9,"baseatk":3,"skills":[{"skill":"Fly","value":11},{"skill":"Perception","value":9}],"source":"PFS S5-08"},{"name":"Uori","cr":3,"xp":800,"race":"gillman","age_category":"Old","classes":[{"class":"oracle","level":4}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["aquatic"],"init":-4,"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 armor","hp":33,"hd":"4d8+12","hd_value":4,"fort":2,"ref":1,"will":7,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"quarterstaff +3 (1d6-2)","ranged":"light crossbow +5 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","spellsknown_caster":"oracle","spellsknown_caster_level":4,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"cure moderate wounds"},{"spell":"slipstream"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cure light wounds"},{"spell":"obscuring mist"},{"spell":"sanctuary"},{"spell":"summon monster I"},{"spell":"touch of the sea"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"detect magic"},{"spell":"light"},{"spell":"purify food and drink"},{"spell":"read magic"},{"spell":"stabilize"}]}],"mystery":"waves","strength":7,"dexterity":11,"constitution":12,"intelligence":10,"wisdom":12,"charisma":20,"baseatk":5,"cmb":3,"cmd":13,"feats":[{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":12},{"skill":"Heal","value":5},{"skill":"Knowledge (history)","value":4},{"skill":"Knowledge (religion)","value":5},{"skill":"Linguistics","value":1},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":4},{"skill":"Survival","value":2},{"skill":"Swim","value":9}],"languages":["Aboleth","Common; lip reading"],"sq":["amphibious","enchantment resistance","oracle's curse (deaf)","revelations (fluid travel, water sight)","water dependence"],"gear":"mwk chain shirt, light crossbow with 20 bolts, quarterstaff, 3 gp, oil of silence, potions of cure light wounds (2), wand of shield of faith (CL 6th, 10 charges), thunderstones (2)","during_combat":"If provoked into combat, Uori casts obscuring mist and walks out onto the water's surface with his fluid travel revelation. He then casts sanctuary in the hopes that the PCs will simply leave the site without further incident. If the PCs press the attack, he uses a mix of spells and crossbow bolts in his attempt to repel the land-dwelling invaders.","morale":"Uori refuses to leave this holy site and continues to fight until the PCs leave the chamber.","source":"PFS S5-08, Pathfinder RPG Advanced Player's Guide 42, Pathfinder RPG Advanced Race Guide 188"},{"name":"Minotaur","cr":4,"xp":1200,"race":"Minotaur","age_category":"Adult","alignment":"CE","size":"Large","type":"monstrous humanoid","init":0,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":9,"ac_flat_footed":14,"ac_mods":"+5 natural, -1 size","hp":45,"hd":"6d10+12","hd_value":6,"fort":6,"ref":5,"will":5,"defensive_abilities":["natural cunning"],"speed":[{"type":"land","speed":30}],"melee":"broken battleaxe +7 (2d6+4/x2) and gore +4 (1d6+2)","ranged":"javelin +5 (1d8+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"powerful charge","details":"gore +11, 2d6+6"}],"strength":19,"dexterity":10,"constitution":15,"intelligence":7,"wisdom":10,"charisma":8,"baseatk":6,"cmb":11,"cmd":21,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":5},{"skill":"Perception","value":10},{"skill":"Stealth","value":2},{"skill":"Survival","value":10}],"languages":["Giant"],"gear":"broken greataxe, javelins (3)","during_combat":"The minotaur attempts to finish off Janira with a single strike. Once Janira is down, the minotaur turns its attention to the PCs if they have joined the fight. Otherwise, it inspects the fallen halfling and finishes her off. Outnumbered against the PCs, the minotaur tries to make its attacks count by forgoing the use of its Power Attack feat, and it spreads out its attacks against multiple targets if possible to fend off the many attackers.","morale":"Though not overly intelligent, the minotaur can clearly recognize when it's outnumbered and in a losing battle. It attempts to flee if reduced to 10 or fewer hit points.","source":"PFS S5-08"},{"name":"Janira Gavix","cr":3,"xp":800,"race":"halfling","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":4}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["halfling"],"init":6,"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +2 Dex, +1 size","hp":25,"hd":"4d8+4","hd_value":4,"fort":3,"ref":7,"will":4,"save_mods":"+2 vs. fear, +4 vs. bardic performance, language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"mwk whip +4 (1d2-1 nonlethal)","ranged":"light crossbow +6 (1d6/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 14 rounds/day","details":"countersong, distraction, fascinate, inspire competence +2, inspire courage +1"}],"spellsknown_caster":"bard","spellsknown_caster_level":4,"spellsknown_concentration":8,"spellsknown":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"gallant inspiration"},{"spell":"glitterdust"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"comprehend languages"},{"spell":"cure light wounds"},{"spell":"expeditious retreat"},{"spell":"grease"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"read magic"},{"spell":"unwitting ally"}]}],"strength":8,"dexterity":15,"constitution":12,"intelligence":14,"wisdom":8,"charisma":18,"baseatk":3,"cmb":1,"cmd":13,"feats":[{"feat":"Improved Initiative"},{"feat":"Lingering Performance"}],"skills":[{"skill":"Appraise","value":6},{"skill":"Bluff","value":8},{"skill":"Diplomacy","value":8},{"skill":"Handle Animal","value":5},{"skill":"Knowledge (arcana, history)","value":11},{"skill":"Knowledge (dungeoneering, engineering, geography, local, nature, religion)","value":8},{"skill":"Linguistics","value":7},{"skill":"Perception","value":8},{"skill":"Perform (oratory)","value":11},{"skill":"Sense Motive","value":3},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":9},{"skill":"Use Magic Device","value":11}],"languages":["Common","Dwarven","Elven","Giant","Halfling","Orc"],"sq":["bardic knowledge +2","fleet of foot","versatile performance (oratory)"],"gear":"mwk chain shirt, light crossbow with 30 bolts, mwk whip, antitoxin, sunrods (2), potion of barkskin, potions of cure light wounds (2), potion of feather step, potion of vanish, scroll of entangle, scroll of gust of wind, scroll of identify, scroll of mage armor (CL 6), scroll of obscuring mist, wand of burning hands (CL 3rd, 4 charges), wand of cure light wounds (CL 3rd, 8 charges), acid, alchemist's fire (2), holy water, smokestick, tanglefoot bags (2), thunderstone","source":"PFS S5-08"},{"name":"Valais Durant","cr":5,"xp":1600,"race":"unfettered eidolon","age_category":"Adult","alignment":"LG","size":"Medium","type":"outsider","sub_types":["native"],"init":6,"senses":["darkvision 60 ft."],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":45,"hd":"6d10+12","hd_value":6,"fort":7,"ref":4,"will":7,"resists":["acid 5","cold 5","electricity 5","fire 5  Defensive Abilities evasion"],"speed":[{"type":"land","speed":35}],"melee":"2 claws +10 (1d4+4 plus 1d6 acid), gore +10 (1d6+4 plus 1d6 acid)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":14,"constitution":14,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":6,"cmb":10,"cmd":22,"feats":[{"feat":"Fleet"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Diplomacy","value":9},{"skill":"Knowledge (dungeoneering)","value":7},{"skill":"Knowledge (history)","value":4},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":6},{"skill":"Stealth","value":8}],"languages":["Common","Abyssal"],"sq":["evolution points (arms, claws, energy attacks [acid], gore, legs, resistance [acid, cold, electricity, fire])","stitched abomination"],"special_abilities":[{"type":"Stitched Abomination","kind":"Ex","details":"Valais is affected by spells as though she were an eidolon. In addition, spells or effects that have a special effect against humanoids or demons can also affect her, albeit with a +4 resistance bonus on any saving throws to resist the effect. For the purposes of the favored enemy class feature and similar abilities, she is only an outsider with the native subtype."}],"during_combat":"Despite her demonic appearance, Valais has no interest in taking lives. She spends her actions sobbing and remaining solely on the defensive.","morale":"If Valias is reduced below 23 hit points, her demonic aspects assert control, and she begins attacking anything in sight until she's rendered unconscious or slain.","source":"PFS S5-09, Pathfinder RPG Bestiary 3 110"},{"name":"Valais Durant Subtier 6-7","cr":8,"xp":4800,"race":"unfettered eidolon","age_category":"Adult","alignment":"LG","size":"Medium","type":"outsider","sub_types":["native"],"init":7,"senses":["darkvision 60 ft."],"ac":25,"ac_touch":13,"ac_flat_footed":22,"ac_mods":"+3 Dex, +12 natural","hp":75,"hd":"10d10+20","hd_value":10,"fort":9,"ref":8,"will":9,"immunities":["electricity"],"resists":["acid 5","cold 5","fire 5  Defensive Abilities evasion"],"speed":[{"type":"land","speed":35}],"melee":"2 claws +14 (1d6+4 plus 1d6 acid), gore +14 (1d6+4 plus 1d6 acid), bite +14 (1d6+4 plus 1d6 acid)","space":"5 ft.","reach":"5 ft.","strength":19,"dexterity":16,"constitution":14,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":10,"cmb":14,"cmd":27,"feats":[{"feat":"Fleet"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Diplomacy","value":13},{"skill":"Knowledge (dungeoneering)","value":11},{"skill":"Knowledge (history)","value":6},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":8},{"skill":"Stealth","value":11}],"languages":["Common","Abyssal"],"sq":["evolution points (arms, bite, claws, energy attacks [acid], gore, immunity [electricity], improved natural armor [2], legs, resistance [acid, cold, fire])","stitched abomination"],"special_abilities":[{"type":"Stitched Abomination","kind":"Ex","details":"Valais is affected by spells as though she were an eidolon. In addition, spells or effects that have a special effect against humanoids or demons can also affect her, albeit with a +4 resistance bonus on any saving throws to resist the effect. For the purposes of the favored enemy class feature and similar abilities, she is only an outsider with the native subtype."}],"during_combat":"Despite her demonic appearance, Valais has no interest in taking lives. She spends her actions sobbing and remaining solely on the defensive.","morale":"If Valais is reduced below 38 hit points, her demonic aspects assert control, and she begins attacking anything in sight until she's rendered unconscious or slain.","source":"PFS S5-09, Pathfinder RPG Bestiary 3 110"},{"name":"Demonic Eidolon","cr":4,"xp":1200,"race":"unfettered eidolon","age_category":"Adult","alignment":"CE","size":"Small","type":"outsider","sub_types":["native"],"init":3,"senses":["darkvision 60 ft."],"ac":21,"ac_touch":15,"ac_flat_footed":17,"ac_mods":"+3 Dex, +1 dodge, +6 natural, +1 size","hp":37,"hd":"5d10+10","hd_value":5,"fort":5,"ref":6,"will":4,"immunities":["fire"],"speed":[{"type":"fly","speed":30,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"2 claws +8 (1d3+2 plus 1d6 fire), bite +8 (1d4+2 plus 1d6 fire)","ranged":"boiling blood +9 touch (2d4 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"boiling blood"}],"strength":14,"dexterity":16,"constitution":12,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":5,"cmb":6,"cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Escape Artist","value":7},{"skill":"Fly","value":15},{"skill":"Intimidate","value":4},{"skill":"Perception","value":8},{"skill":"Stealth","value":15}],"languages":["Common"],"sq":["evolutions (arms, bite, claws, energy attacks [fire], flight, immunity [fire], legs)","stitched abomination"],"special_abilities":[{"type":"Boiling Blood","kind":"Ex","details":"A demonic eidolon can scoop and hurl a handful of the fluid in the cauldron as a standard action. This attack is a ranged touch attack with a range increment of 10 feet."},{"type":"Stitched Abomination","kind":"Ex","details":"A demonic eidolon is affected by spells as though it were an eidolon. In addition, spells or effects that have a special effect against humanoids or demons can also affect it, albeit with a +4 resistance bonus on saving throws to resist the effect. For the purposes of the favored enemy class feature and similar abilities, the eidolon is only an outsider with the native subtype."}],"during_combat":"Once alerted, the eidolons emerge from the cauldron and fling boiling blood at the interlopers. If approached, they prefer to fly to the ceiling and dive at vulnerable-looking targets. If two or more enemies move to the room's lower level, the eidolons attempt to break the chains holding up the cauldron.","morale":"Having nowhere else to go, the eidolons fight to the death.","source":"PFS S5-09, Pathfinder RPG Bestiary 3 110"},{"name":"Demonic Eidolon Subtier 6-7","cr":6,"xp":2400,"race":"unfettered eidolon","age_category":"Adult","alignment":"CE","size":"Small","type":"outsider","sub_types":["native"],"init":3,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+3 Dex, +1 dodge, +8 natural, +1 size","hp":60,"hd":"8d10+16","hd_value":8,"fort":7,"ref":5,"will":6,"immunities":["fire"],"speed":[{"type":"fly","speed":30,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"2 claws +11 (1d3+2 plus 1d6 fire), bite +11 (1d4+2 plus 1d6 fire), sting +11 (1d3+2 plus 1d6 fire and poison)","ranged":"blood +12 touch (4d4)","space":"5 ft.","reach":"5 ft. (10 ft. with sting)","special_attacks":[{"type":"boiling blood"},{"type":"poison"}],"strength":15,"dexterity":17,"constitution":12,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":8,"cmb":9,"cmd":23,"feats":[{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Escape Artist","value":8},{"skill":"Fly","value":16},{"skill":"Intimidate","value":5},{"skill":"Perception","value":11},{"skill":"Stealth","value":18}],"languages":["Common"],"sq":["evolutions (arms, bite, claws, energy attacks [fire], flight, immunity [fire], legs, reach [sting], sting, tail)","stitched abomination"],"special_abilities":[{"type":"Boiling Blood","kind":"Ex","details":"A demonic eidolon can scoop and hurl a handful of the fluid in the cauldron as a standard action. This attack is a ranged touch attack with a range increment of 10 feet."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 15; frequency 1/round for 4 rounds; effect 1d4 Str; cure 1 consecutive save."},{"type":"Stitched Abomination","kind":"Ex","details":"A demonic eidolon is affected by spells as though it were an eidolon. In addition, spells or effects that have a special effect against humanoids or demons can also affect it, albeit with a +4 resistance bonus on saving throws to resist the effect. For the purposes of the favored enemy class feature and similar abilities, the eidolon is only an outsider with the native subtype."}],"during_combat":"Once alerted, the eidolons emerge from the cauldron and fling boiling blood at the interlopers. If approached, they prefer to fly to the ceiling and dive at vulnerable-looking targets using Spring Attack. If two or more enemies move to the room's lower level, the eidolons attempt to break the chains holding up the cauldron.","morale":"Having nowhere else to go, the eidolons fight to the death.","source":"PFS S5-09, Pathfinder RPG Bestiary 3 110"},{"name":"Karsos","cr":6,"xp":2400,"race":"minotaur","gender":"Male","age_category":"Adult","alignment":"CE","size":"Large","type":"undead","sub_types":["augmented monstrous humanoid","incorporeal"],"templates_applied":"ghost","init":0,"senses":["darkvision 60 ft."],"ac":10,"ac_touch":10,"ac_flat_footed":10,"ac_mods":"+1 deflection, -1 size","hp":33,"hd":"6d8+6","hd_value":6,"fort":5,"ref":5,"will":5,"defensive_abilities":["incorporeal channel resistance +4"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +5 touch (6d6, Fort DC 14 half)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"lure of the labyrinth","details":"DC 14"}],"dexterity":10,"intelligence":7,"wisdom":10,"charisma":12,"baseatk":6,"cmb":7,"cmb_special":"+9 bull rush","cmd":18,"cmd_special":"20 vs. bull rush","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Fly","value":6},{"skill":"Intimidate","value":7},{"skill":"Perception","value":14},{"skill":"Stealth","value":10},{"skill":"Survival","value":10}],"languages":["Giant"],"sq":["natural cunning","phantasmagoria (DC 16)"],"special_abilities":[{"type":"Lure of the Labyrinth","kind":"Su","details":"As a move action, Karsos can utter the name of a creature in his maze, which fascinates the creature and entices it to wander aimlessly. On the creature's next turn, it spends a move action traveling its speed in a random direction, after which it can act normally as long as it doesn't retrace its steps. Karsos can only affect a creature with this ability once per 24-hour period, and a DC 14 Will save negates this effect."},{"type":"Natural Cunning","kind":"Ex","details":"Although minotaurs are not especially intelligent, they possess innate cunning and logical ability. This gives them immunity to maze spells and prevents them from ever becoming lost. Further, they are never caught flat-footed."},{"type":"Phantasmagoria","kind":"Su","details":"Karsos was tied to his former maze abode and this persists into his undeath. Once per day, Karsos can create an elaborate illusion within the ruins of the maze that restores it to its former glory. This illusion functions similarly to the spell mirage arcana in combination with multiple major images, allowing Karsos to recreate the maze. Karsos can even incorporate himself into the illusion as if he were under the effects of the spell alter self. The illusion is treated as a 6th-level spell created at CL 6th. If any part of the illusion is dispelled, the entire illusion fades. The save DC is Charisma-based."}],"before_combat":"Karsos stalks the PCs as they navigate the maze, waiting for them to become separated by an illusion or circumstance before striking.","during_combat":"Karsos attacks by striking through walls, moving ahead of the PCs to wait just around the next corner, and staying mobile.","morale":"Karsos believes the PCs to be Mendevian Crusaders, which enrages him. He fights until destroyed.","source":"PFS S5-09, Pathfinder RPG Bestiary 144, 206"},{"name":"Karsos Subtier 6-7","cr":9,"xp":6400,"race":"minotaur","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of baphomet","level":5}],"alignment":"CE","size":"Large","type":"undead","sub_types":["augmented monstrous humanoid","incorporeal"],"templates_applied":"ghost","init":0,"senses":["darkvision 60 ft."],"ac":12,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 deflection, -1 size","hp":98,"hd":"6d8+5d8+49","hd_value":11,"fort":11,"ref":6,"will":11,"defensive_abilities":["incorporeal channel resistance +4"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +8 touch (9d6, Fort. DC 18)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 15, 3d6"},{"type":"lure of the labyrinth","details":"DC 16"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"speak with animals","details":"8 rounds/day"}]},{"frequency":"5/day","spells":[{"spell":"fury of the Abyss"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":5,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":3,"spell_slots":2,"spells":[{"spell":"bestow curse"},{"spell":"dominate animal","type":"domain"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"eagle's splendor"},{"spell":"hold animal","type":"domain"},{"spell":"hold person"},{"spell":"undetectable alignment"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cause fear"},{"spell":"command"},{"spell":"doom","type":"domain"},{"spell":"obscuring mist"},{"spell":"summon monster I"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"virtue"}]}],"spelldomains":"Animal, Demon","dexterity":10,"intelligence":10,"wisdom":14,"charisma":16,"baseatk":9,"cmb":10,"cmb_special":"+12 bull rush","cmd":23,"cmd_special":"25 vs. bull rush","feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":6},{"skill":"Intimidate","value":12},{"skill":"Knowledge (religion)","value":7},{"skill":"Linguistics","value":4},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":18},{"skill":"Survival","value":15}],"languages":["Common","Giant"],"sq":["animal companion (none)","natural cunning","phantasmagoria"],"special_abilities":[{"type":"Lure of the Labyrinth","kind":"Su","details":"As a move action, Karsos can utter the name of a creature in his maze, which fascinates the creature and entices it to wander aimlessly. On the creature's next turn, it spends a move action traveling its speed in a random direction, after which it can act normally as long as it doesn't retrace its steps. Karsos can only affect a creature with this ability once per 24-hour period, and a DC 16 Will save negates this effect."},{"type":"Natural Cunning","kind":"Ex","details":"Although minotaurs are not especially intelligent, they possess innate cunning and logical ability. This gives them immunity to maze spells and prevents them from ever becoming lost. Further, they are never caught flat-footed."},{"type":"Phantasmagoria","kind":"Su","details":"Karsos was tied to his former maze abode and this persists into his undeath. Once per day, Karsos can create an elaborate illusion within the ruins of the maze that restores it to its former glory. This illusion functions similarly to the spell mirage arcana in combination with multiple major images, allowing Karsos to recreate the maze. Karsos can even incorporate himself into the illusion as if he were under the effects of the spell alter self. The illusion is treated as a 6th-level spell created at CL 11th. If any part of the illusion is dispelled, the entire illusion fades. The save DC is Charisma-based."}],"source":"PFS S5-09, Pathfinder RPG Bestiary 144, 206"},{"name":"Dorok Bear's Claw","cr":8,"xp":4800,"race":"Human (Kellid)","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":9}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"senses":["scent"],"ac":19,"ac_touch":11,"ac_flat_footed":17,"ac_mods":"+5 armor, +1 deflection, +1 Dex, +1 dodge, +3 natural, -2 rage","hp":118,"hd":"9d12+54","hd_value":9,"fort":11,"ref":5,"will":7,"defensive_abilities":["improved uncanny dodge","trap sense +3"],"dr":"2/-","speed":[{"type":"land","speed":30}],"melee":"2 claws +17 (1d6+7) or mwk longspear +14 (1d8+9/x3)","ranged":"javelin +10 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"22 rounds/day"},{"type":"rage powers","details":"beast totem, increased damage reduction, lesser beast totem, scent"}],"strength":23,"dexterity":13,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":9,"cmb":15,"cmd":26,"feats":[{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Power Attack"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":12},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":13},{"skill":"Stealth","value":4},{"skill":"Survival","value":13},{"skill":"Swim","value":11}],"languages":["Hallit"],"sq":["fast movement","ursine prosthesis"],"special_abilities":[{"type":"Ursine Prosthesis","kind":"Ex","details":"Dorok is able to use his prosthetic \"hand\" to help him perform two-handed tasks. He takes no penalties on skill checks due to his condition unless the task requires fine detail or careful manipulation. He is also able to wield two-handed weapons with the aid of his prosthesis, albeit with a -2 penalty on attack rolls."}],"gear":"+1 hide armor, mwk longspear, javelins (5), amulet of mighty fists +1, cloak of resistance +1, ring of protection +1, antitoxin, backpack, bedroll, climber's kit, rope, 46 gp, potions of cure moderate wounds (2)","during_combat":"Dorok's tactics are simple but efficient; he begins to rage as soon as combat begins and targets any obvious arcane casters first. While raging, Dorok's right hand transforms into a vicious bear-like claw, similar to the claw strapped to his left arm. Dorok frequently uses Power Attack as he claws enemies apart, relying on his rage powers to overcome magical defenses.","morale":"With the pride of the Red Winter tribe at stake, Dorok fights to the death unless otherwise commanded to stand down by one of the tribe's leaders.","base_statistics":"While he's not raging, Dorok's statistics are AC 18, touch 13, flat-footed 16; hp 100; Fort +9, Will +5; Melee mwk longspear +12/+7 (1d8+6/x3); Str 19, Con 14; CMB +13, CMD 26; Skills Climb +10, Swim +9.","source":"PFS S5-10"},{"name":"Red Winter Warrior","cr":6,"xp":2400,"race":"Human (Kellid)","age_category":"Adult","classes":[{"class":"barbarian","level":7}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":14,"ac_touch":9,"ac_flat_footed":13,"ac_mods":"+5 armor, +1 Dex, -2 rage","hp":93,"hd":"7d12+42","hd_value":7,"fort":10,"ref":4,"will":6,"defensive_abilities":["improved uncanny dodge","trap sense +2"],"dr":"1/-","speed":[{"type":"land","speed":30}],"melee":"+1 longspear +14 (1d8+10/x3)","ranged":"mwk composite longbow +9 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"18 rounds/day"},{"type":"rage powers","details":"knockback, quick reflexes, rolling dodge +2"}],"strength":22,"dexterity":13,"constitution":18,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":7,"cmb":13,"cmd":22,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Climb","value":10},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":11},{"skill":"Stealth","value":3},{"skill":"Survival","value":11},{"skill":"Swim","value":11}],"languages":["Hallit"],"sq":["fast movement"],"gear":"+1 hide armor, +1 longspear, mwk composite longbow with 20 arrows, cloak of resistance +1, backpack, bedroll, climber's kit, rope, 46 gp, potions of cure moderate wounds (2)","during_combat":"The Red Winter warriors begin to rage as soon as combat begins. They use their reach, knockback rage power, and additional attacks of opportunity to control melee threats. If targeted by ranged attacks, the warriors utilize their rolling dodge rage power.","morale":"The Red Winter warriors fight bravely, but if Dorok dies, they withdraw to warn the rest of the tribe.","base_statistics":"While not raging, the barbarians' statistics are AC 16, touch 11, flat-footed 15; hp 79; Fort +8, Will +4; Melee +1 longspear +12/+7 (1d8+7/x3); Str 18, Con 14; CMB +11, CMD 22; Skills Climb +8, Swim +9.","source":"PFS S5-10"}];
